-- Replace the website catalog with the Quality Light inventory sheet (جرد المواد).
--
-- * 1324 lighting and wiring products (tools, fixings, pipes and consumables excluded)
-- * Price: the sheet's selling price; if empty, the average real selling price (net sales ÷ qty
--   sold, rounded to 5 fils, skipped when below cost); otherwise 0 = "ask for price"
-- * Stock is not tracked from the sheet (it is unreliable): every product is orderable
-- * Previous demo products are hidden (is_active = false), not deleted, so old orders keep working
-- * Purchase cost is NOT stored: product rows are publicly readable

BEGIN;

ON CONFLICT (slug) DO UPDATE SET name_en = EXCLUDED.name_en, name_ar = EXCLUDED.name_ar, is_active = true;

CREATE TEMP TABLE inventory_import (
  sku text, slug text, name_en text, name_ar text, price numeric, category_slug text,
  description_en text, description_ar text, is_bestseller boolean, is_featured boolean, image_url text
) ON COMMIT DROP;


-- Hide everything that is not in the sheet
UPDATE public.products SET is_active = false
WHERE sku IS NULL OR sku NOT IN (SELECT sku FROM inventory_import);

-- Insert new items, refresh existing ones (matched by SKU = item code)
  short_description_en, short_description_ar, stock_quantity, low_stock_threshold, is_active, is_bestseller, is_featured, is_new)
SELECT i.sku, i.slug, i.name_en, i.name_ar, i.price, NULL, c.id, i.description_en, i.description_ar,
  i.description_en, i.description_ar, 9999, 0, true, i.is_bestseller, i.is_featured, false
FROM inventory_import i
JOIN public.categories c ON c.slug = i.category_slug
WHERE NOT EXISTS (SELECT 1 FROM public.products p WHERE p.sku = i.sku);

UPDATE public.products p
SET name_ar = i.name_ar, base_price = i.price, sale_price = NULL, category_id = c.id,
    stock_quantity = 9999, low_stock_threshold = 0, is_active = true,
    is_bestseller = i.is_bestseller, is_featured = i.is_featured
FROM inventory_import i
JOIN public.categories c ON c.slug = i.category_slug
WHERE p.sku = i.sku;

-- A photo for every imported product that has none yet
SELECT p.id, i.image_url, true, 0, i.name_en, i.name_ar
FROM inventory_import i
JOIN public.products p ON p.sku = i.sku
WHERE NOT EXISTS (SELECT 1 FROM public.product_images pi WHERE pi.product_id = p.id);

COMMIT;
